<?php require_once '../includes/db.php';require_once '../includes/functions.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$id=(int)$_POST['id'];$status=$_POST['status']??'';if(in_array($status,['Placed','Processing','Shipped','Completed','Cancelled'],true)){$s=$conn->prepare("UPDATE orders SET status=? WHERE id=?");$s->bind_param('si',$status,$id);$s->execute();flash('Order status updated.');}header('Location: orders.php');exit;}$orders=$conn->query("SELECT * FROM orders ORDER BY id DESC")->fetch_all(MYSQLI_ASSOC);$title='Orders';$adminPage=true;include '../includes/header.php';?><div class="heading"><div><small>FULFILMENT</small><h2>Orders</h2></div></div><div class="panel scroll"><table><tr><th>Order</th><th>Customer</th><th>Contact / Address</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['customer_name'])?></td><td><?=e($o['email'])?><br><?=e($o['phone'])?><br><?=e($o['address'])?></td><td>₹<?=number_format($o['total'],2)?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['Placed','Processing','Shipped','Completed','Cancelled'] as $st):?><option <?=$st===$o['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn">Save</button></form></td></tr><?php endforeach;?></table></div><?php include '../includes/footer.php';?>